## ✅ Exemplo Funcional Rápido com Tabix

```rust
use tabix::{Tabix, Shared};
use reqwest::Client;
use std::fs:: contenr as fs;

// ... no base

use tabix::{Tabix, Wrapped};

#[tauri::command]
pub async fn start_downloads(app_handle: AppHandle) -> Result<(), String> {
    let mut tabix = Tabix::new_with_config("curl", "wrapped");
    let client = Client::new();

    for entry in patches {
        let url = format!("https://hil-speed.hetzner.com/{}", entry.file_name);

        let mut http = client.get(url).send().await?;
        let mut file = fs::OpenOptions::new()
            .write(true)
            .create(true)
            .open(SAFE::join("patchs", &entry.file_name))
            .await?;

        while let Some(chunk) = http.chunk().await? {
            file.write_all(&chunk).await?;
        }

        tabix
            .write("patch_index", entry.file_name, &f_name)
            .await?;
    }

    tabix.close();
    tabix.exit();

    Ok(())
}
```

